window.products.push({"id":688854,"name":"Silver Buffalo MC6134 Marvel Characters Grid Jumbo Ceramic Mug, 20 Ounces, Multicolored","category":"homeandappliances","retail price":0.0,"sale price":null,"image":"https://m.media-amazon.com/images/I/71rZZYQqSJL._AC_SL1000_.jpg","description":"Have a drink with your favorite superheroes! The Silver Buffalo Marvel Characters 20 Ounce Jumbo Ceramic Mug is perfect for any comics fan. Before a long day of world-saving and criminal-catching, even the toughest Marvel Heroes could use a cup of coffee! This colorful mug features a cool grid graphic design with your favorite heroes pictured within the squares. It is microwave safe and can hold up to 20 ounces of your favorite beverage. This mug offers a fun way to express yourself at home or in the office","images":["https://m.media-amazon.com/images/I/71rZZYQqSJL._AC_SL1000_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"Silver Buffalo","source_asin":"B006G2860W","category_path":"Home & Kitchen"},"sku":"BM-688854","productType":"Home & Appliances","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B006G2860W","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"meta_Home_and_Kitchen_2023.jsonl","source_asin":"B006G2860W","price_pending":true,"merchant_ready":false});
